package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId string // PIC X(5) @0 len=5
	OrStat string // PIC X(1) @5 len=1
	OrQty int64 // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsTotal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal // PIC 9(10)V99 len=12 = 0
var WsNewCount int64 // PIC 99 len=2 = 0
var WsShipCount int64 // PIC 99 len=2 = 0
var WsCancelCount int64 // PIC 99 len=2 = 0
var WsInvalid int64 // PIC 99 len=2 = 0
var WsBadQty int64 // PIC 99 len=2 = 0
var WsQtyEd string // PIC ZZ9 len=3
var WsPriceEd string // PIC Z,ZZ9.99 len=8
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var curOrder OrderRec

var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func setInputDone() {
	WsEofFlag = "Y"
}

func parseDigitsOnly(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return v
}

func parseRecord(line string) OrderRec {
	// pad right with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	id := line[0:5]
	stat := line[5:6]
	qtyStr := line[6:9]
	priceStr := line[9:15]
	qty := parseDigitsOnly(qtyStr)
	// price digits only implied V99
	pn := parseDigitsOnly(priceStr)
	price := decimal.New(pn, -2)
	// store truncation to field sizes (low-order digits)
	qty = qty % 1000
	// price keep low order 6 digits
	pnMod := pn % 1000000
	price = decimal.New(pnMod, -2)
	return OrderRec{OrId: id, OrStat: stat, OrQty: qty, OrPrice: price}
}

func formatEdited(val decimal.Decimal, pattern string) string {
	// split pattern
	dotIdx := strings.Index(pattern, ".")
	var intPat string
	fracLen := 0
	if dotIdx < 0 {
		intPat = pattern
	} else {
		intPat = pattern[:dotIdx]
		fracPart := pattern[dotIdx+1:]
		fracLen = len(fracPart)
	}
	// count placeholders in intPat
	n := 0
	for i := 0; i < len(intPat); i++ {
		if intPat[i] == 'Z' || intPat[i] == '9' {
			n++
		}
	}
	absVal := val.Abs().Truncate(int32(fracLen))
	shiftedStr := absVal.Shift(int32(fracLen)).StringFixed(0)
	// shiftedStr may contain "-" ? abs so no. May contain "."? No since integer.
	shiftedStr = strings.TrimSpace(shiftedStr)
	neg := false
	if strings.HasPrefix(shiftedStr, "-") {
		neg = true
		shiftedStr = shiftedStr[1:]
	}
	// remove any decimal point (shouldn't)
	if idx := strings.Index(shiftedStr, "."); idx >= 0 {
		shiftedStr = shiftedStr[:idx]
	}
	if shiftedStr == "" {
		shiftedStr = "0"
	}
	// ensure only digits (strip sign/exponent)
	digits := ""
	for i := 0; i < len(shiftedStr); i++ {
		if shiftedStr[i] >= '0' && shiftedStr[i] <= '9' {
			digits += string(shiftedStr[i])
		}
	}
	if digits == "" {
		digits = "0"
	}
	// pad left to fracLen+1
	need := fracLen + 1
	if len(digits) < need {
		digits = strings.Repeat("0", need-len(digits)) + digits
	}
	var fracStr string
	var intFull string
	if fracLen > 0 {
		fracStr = digits[len(digits)-fracLen:]
		intFull = digits[:len(digits)-fracLen]
	} else {
		fracStr = ""
		intFull = digits
	}
	// strip leading zeros for intFull? keep at least "0"
	intFull = strings.TrimLeft(intFull, "0")
	if intFull == "" {
		intFull = "0"
	}
	// keep low-order n digits
	var d string
	if len(intFull) > n {
		d = intFull[len(intFull)-n:]
	} else {
		d = strings.Repeat("0", n-len(intFull)) + intFull
	}
	// find first non-zero
	firstNZ := -1
	for i := 0; i < len(d); i++ {
		if d[i] != '0' {
			firstNZ = i
			break
		}
	}
	var b strings.Builder
	pi := 0 // index into d
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == 'Z' || c == '9' {
			digit := d[pi]
			if firstNZ == -1 {
				// all zero
				if c == 'Z' {
					// if this is the very last placeholder and pattern has only Z? then should print 0?
					// But our patterns all end with 9, so space.
					// Check if any later placeholder is '9': if this is last placeholder, print 0? For safety:
					// look ahead for any '9' later
					hasLater9 := false
					for k := i + 1; k < len(intPat); k++ {
						if intPat[k] == '9' {
							hasLater9 = true
							break
						}
					}
					if c == 'Z' && !hasLater9 && pi == n-1 {
						b.WriteByte('0')
					} else {
						b.WriteByte(' ')
					}
				} else {
					b.WriteByte(digit)
				}
			} else {
				if pi < firstNZ {
					// suppressed zone
					if c == 'Z' {
						b.WriteByte(' ')
					} else {
						b.WriteByte(digit)
					}
				} else {
					b.WriteByte(digit)
				}
			}
			pi++
		} else if c == ',' {
			if firstNZ == -1 {
				b.WriteByte(' ')
			} else {
				if pi <= firstNZ {
					b.WriteByte(' ')
				} else {
					b.WriteByte(',')
				}
			}
		} else {
			b.WriteByte(c)
		}
	}
	if fracLen > 0 {
		b.WriteByte('.')
		b.WriteString(fracStr)
	}
	_ = neg
	return b.String()
}

func storeTotal(v decimal.Decimal) decimal.Decimal {
	modulus := decimal.NewFromInt(100000000) // 10^8
	if v.IsNegative() {
		m := v.Mod(modulus)
		// Mod sign follows dividend; adjust to keep low-order? For negative, COBOL keeps sign; wrap not needed for tests
		return m
	}
	return v.Mod(modulus)
}

func storeGrand(v decimal.Decimal) decimal.Decimal {
	modulus := decimal.NewFromInt(10000000000) // 10^10
	if v.IsNegative() {
		return v.Mod(modulus)
	}
	return v.Mod(modulus)
}

func fmtPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func MAINPARA() {
	// OPEN INPUT ORDER-FILE
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			data = []byte{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	s := string(data)
	if len(s) == 0 {
		inputLines = nil
	} else {
		// normalize: split by \n
		parts := strings.Split(s, "\n")
		endedWithNL := strings.HasSuffix(s, "\n")
		if endedWithNL {
			// drop final terminator element
			parts = parts[:len(parts)-1]
		}
		inputLines = make([]string, 0, len(parts))
		for _, p := range parts {
			if strings.HasSuffix(p, "\r") {
				p = p[:len(p)-1]
			}
			inputLines = append(inputLines, p)
		}
	}
	inputIdx = 0
	inputOpen = true
	WsEofFlag = "N"
	WsTotal = decimal.NewFromInt(0)
	WsGrand = decimal.NewFromInt(0)
	// counts already 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	inputOpen = false
	SUMMARYPARA()
}

func READPARA() {
	if !inputOpen || inputIdx >= len(inputLines) {
		setInputDone()
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	curOrder = parseRecord(line)
}

func PROCESSPARA() {
	WsTotal = decimal.NewFromInt(0)
	if curOrder.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", curOrder.OrId)
	} else if curOrder.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		q := decimal.NewFromInt(curOrder.OrQty)
		v := q.Mul(curOrder.OrPrice).Truncate(2)
		WsTotal = storeTotal(v)
		WsNewCount = (WsNewCount + 1) % 100
		SHOWPARA()
	} else if curOrder.OrStat == "S" {
		q := decimal.NewFromInt(curOrder.OrQty)
		factor := decimal.New(105, -2) // 1.05
		v := q.Mul(curOrder.OrPrice).Mul(factor).Round(2)
		WsTotal = storeTotal(v)
		WsShipCount = (WsShipCount + 1) % 100
		SHOWPARA()
	} else if curOrder.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		SHOWPARA()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", curOrder.OrId, curOrder.OrStat)
	}
	WsGrand = storeGrand(WsGrand.Add(WsTotal).Truncate(2))
	READPARA()
}

func SHOWPARA() {
	// MOVE OR-QTY TO WS-QTY-ED etc.
	WsQtyEd = formatEdited(decimal.NewFromInt(curOrder.OrQty), "ZZ9")
	WsPriceEd = formatEdited(curOrder.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", curOrder.OrId, curOrder.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARYPARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", fmtPIC99(WsNewCount), fmtPIC99(WsShipCount), fmtPIC99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", fmtPIC99(WsInvalid), fmtPIC99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	MAINPARA()
}
